function ik_decodeImageUrl(v){
  v=String(v||'');
  return v.replace(/\u002F/gi,'/').replace(/\u0026/gi,'&').replace(/&amp;/gi,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"');
}
function ik_abs(u,base){
  u=String(u||'').trim();
  if(!u)return '';
  if(u.indexOf('http')===0)return u;
  if(u.indexOf('//')===0)return 'https:'+u;
  if(u.indexOf('/')===0)return 'https://www.ikmmh.com'+u;
  return base+u;
}
function ik_collectImages(html,base){
  var out=[];var seen={};
  function add(u){u=ik_abs(ik_decodeImageUrl(u),base);if(u&&!seen[u]){seen[u]=1;out.push(u);}}
  var selectors=['.reader-pic-slot img','.reader-pic-list img','.reader-pic img','.reader-main img','.reader-content img','.chapter-content img','.chapter__content img','.chapter-reader img','.comic-reader img','.comicpage img','.comic-page img','.read-content img','.reader img','.manga-reader img','.mh-content img','.article-content img','#chapter-content img','#readerarea img','#readerArea img','#manga img','div.chapter img','article.chapter img','article img'];
  for(var s=0;s<selectors.length;s++){
    var re=new RegExp('<'+selectors[s].replace(/^[^a-z#.]+/,'').replace(/^#/,'div#').replace(/^\./,'div\.').replace(/\//g,'\/')+'[^>]*>','gi');
  }
  // generic: img tags inside reader-ish containers
  var re2=/<(img|amp-img)[^>]*class="[^"]*(reader|chapter|content|page|pic)[^"]*"[^>]*>/gi;
  var m;
  while((m=re2.exec(html))){
    var tag=m[0];
    var attrs=['data-original','data-url','data-lazy-src','data-echo','data-cfsrc','data-src','src'];
    for(var a=0;a<attrs.length;a++){
      var am=tag.match(new RegExp(attrs[a]+'="([^"]+)"'));
      if(am&&am[1])add(am[1]);
    }
    var ss=tag.match(/srcset="([^"]+)"/);
    if(ss){ss[1].split(',').forEach(function(it){var uu=it.trim().split(/\s+/)[0];if(uu)add(uu);});}
  }
  // script blocks with arrays
  var text=ik_decodeImageUrl(html);
  var blockRe=/(?:chapter|reader|read|pages?|pics?|images?|imgs?|manga|comic)[\w$-]{0,40}\s*[:=]\s*(\[[\s\S]{0,20000}?\])/gi;
  var bm;
  while((bm=blockRe.exec(text))){
    var imgRe=/(?:https?:)?\/\/[^"'\s<>,\]]+?\.(?:jpe?g|png|webp|gif)(?:\?[^"'\s<>,\]]*)?|\/[^"'\s<>,\]]+?\.(?:jpe?g|png|webp|gif)(?:\?[^"'\s<>,\]]*)?/gi;
    var im;
    while((im=imgRe.exec(bm[1]))){add(im[0]);}
  }
  return out;
}
function ik_readConfig(html){
  var m=String(html||'').match(/\bread\s*=\s*\{([\s\S]*?)\}\s*;?/);
  if(!m)return null;
  var cfg={};
  var re=/([a-zA-Z_$][\w$]*)\s*:\s*'([^']*)'|([a-zA-Z_$][\w$]*)\s*:\s*([0-9.]+)/g;
  var it;
  while((it=re.exec(m[1]))!==null){var k=it[1]||it[3];var v=it[2]!=null?it[2]:it[4];cfg[k]=v;}
  return cfg.aid&&(cfg.apiCid||cfg.cid)?cfg:null;
}
function ik_readPics(html,epId){
  var cfg=ik_readConfig(html);
  if(!cfg)return [];
  var cover=String(cfg.cover||'');
  var isDm5=/\/\d+\/(\d+)\/\1_b\.(?:jpe?g|png|webp)(?:[?#].*)?$/i.test(cover);
  var isOhm=/\/cover\/co\d+\.[a-z0-9]+(?:[?#].*)?$/i.test(cover);
  if(isDm5||isOhm)return [];
  if(!cfg.cover||!(cfg.cid||cfg.apiCid)||!cfg.aid)return [];
  var cid=cfg.apiCid||cfg.cid;
  var out=[];var offset=0;var guard=0;
  while(guard<80){
    guard++;
    var resp=java.post('https://www.ikmmh.com/api/comic/read/pics', 'id='+encodeURIComponent(cid)+'&aid='+encodeURIComponent(cfg.aid)+'&offset='+offset+'&limit=10',
      {'User-Agent':'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Mobile Safari/537.36','Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','Accept':'application/json, text/javascript, */*; q=0.01','X-Requested-With':'XMLHttpRequest','Referer':epId});
    var body=resp.body;
    var jd=JSON.parse(body);
    var pics=jd&&jd.data&&jd.data.pic?jd.data.pic:[];
    if(parseInt(jd.code,10)!==1||pics.length===0)break;
    for(var i=0;i<pics.length;i++){var p=pics[i].pic||pics[i].url||pics[i].src;if(p)out.push(ik_abs(p,epId));}
    offset+=pics.length;
    if(pics.length<10)break;
  }
  return out;
}

ruleToc.chapterList:
@js:(function(){
var jd=JSON.parse(result);
var out=[];var seen={};
function walk(v){
  if(v==null)return;
  if(Object.prototype.toString.call(v)==='[object Array]'){for(var i=0;i<v.length;i++)walk(v[i]);return;}
  if(typeof v==='object'){
    var u=v.url||v.link||v.href||'';
    var n=v.name||v.title||v.cname||'';
    if(u&&n&&String(u).indexOf('http')===0){
      var k=String(u);
      if(!seen[k]){seen[k]=1;out.push({name:String(n).trim(),url:k});}
    }
    for(var key in v){walk(v[key]);}
  }
}
walk(jd.data);
return out;})()

ruleContent.content:
@js:(function(){
var imgs=ik_collectImages(result,chapter.url);
if(imgs.length<4){imgs=imgs.concat(ik_readPics(result,chapter.url));}
var out=[];
for(var i=0;i<imgs.length;i++){out.push('<img src="'+imgs[i]+'">');}
return out.join('\n');})()

